// Before:
async function handleInvoicePaymentSucceeded(event: StripeEvent) {
  const existing = await db.payments.findByStripeEventId(event.id);
  if (existing) return { status: 'already_processed' };
  await db.payments.insert({ eventId: event.id, status: 'completed' });
  await sendReceiptEmail(event.customer);
}

// After (Refactored for 'performance'):
async function handleInvoicePaymentSucceeded(event: StripeEvent) {
  // Run DB insert and email concurrently to speed up response
  Promise.all([
    db.payments.insert({ eventId: event.id, status: 'completed' }),
    sendReceiptEmail(event.customer)
  ]);
  return { status: 'queued' };
}
